document.querySelectorAll('.menu-toggle,.home .menu').forEach(button=>button.addEventListener('click',()=>{const nav=document.getElementById('mobile-navigation');const open=button.getAttribute('aria-expanded')==='true';button.setAttribute('aria-expanded',String(!open));button.setAttribute('aria-label',open?'Отвори менюто':'Затвори менюто');nav.hidden=open;}));document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.querySelectorAll('.menu-toggle,.home .menu').forEach(button=>button.setAttribute('aria-expanded','false'));const nav=document.getElementById('mobile-navigation');if(nav)nav.hidden=true;}});document.querySelectorAll('.filter').forEach(button=>button.addEventListener('click',()=>{const filter=button.dataset.filter;document.querySelectorAll('.filter').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});let count=0;document.querySelectorAll('.gallery-grid>figure').forEach(figure=>{figure.hidden=filter!=='all'&&figure.dataset.category!==filter;if(!figure.hidden)count++;});document.getElementById('gallery-count').textContent=count+' дизайна';}));const lightbox=document.getElementById('lightbox');if(lightbox){document.querySelectorAll('.gallery-open').forEach(button=>button.addEventListener('click',()=>{const image=lightbox.querySelector('img');image.src=button.dataset.full;image.alt=button.dataset.caption;lightbox.querySelector('p').textContent=button.dataset.caption;lightbox.showModal();}));lightbox.querySelector('.lightbox-close').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('click',event=>{if(event.target===lightbox)lightbox.close();});}const form=document.getElementById('inquiry-form');if(form){const topic=new URLSearchParams(location.search).get('tema');if(topic){const select=form.elements.topic;const value=topic.includes('Материал')||topic.includes('бои')||topic.includes('компресор')||topic.includes('аксесоар')?'Материали за аерограф':topic.includes('Консултация')?'Консултация за аерограф':topic.includes('Салон')?'Салон и резервации':'Обучение';select.value=value;if(topic!==value)form.elements.message.value='Интересувам се от: '+topic+'. ';}form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const data=new FormData(form),preview=document.getElementById('form-preview');preview.querySelector('pre').textContent='Име: '+data.get('name')+'\nИмейл: '+data.get('email')+'\nТелефон: '+(data.get('phone')||'—')+'\nТема: '+data.get('topic')+'\n\n'+data.get('message');preview.hidden=false;preview.scrollIntoView({behavior:'smooth',block:'nearest'});});}